'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var minstd = require( '@stdlib/random/base/minstd' ).factory;
var dkmeansInitRandomPartition = require( './../lib/main.js' );


// FIXTURES //

var ROW_MAJOR_DATA = require( './fixtures/row_major.json' );
var COLUMN_MAJOR_DATA = require( './fixtures/column_major.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dkmeansInitRandomPartition, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 11', function test( t ) {
	t.strictEqual( dkmeansInitRandomPartition.length, 11, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var data;
	var i;

	data = ROW_MAJOR_DATA;

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dkmeansInitRandomPartition( value, data.M, data.N, data.k, new Float64Array( data.X ), data.LDX, new Float64Array( data.out ), data.LDO, new Int32Array( data.k ), 1 );
		};
	}
});

tape( 'the function throws an error if provided a fourth argument which is greater than the second argument', function test( t ) {
	var data;

	data = ROW_MAJOR_DATA;

	t.throws( badValue, RangeError, 'throws an error' );
	t.end();

	function badValue() {
		dkmeansInitRandomPartition( data.order, 2, data.N, 3, new Float64Array( data.X ), data.LDX, new Float64Array( data.out ), data.LDO, new Int32Array( 3 ), 1 );
	}
});

